def extended_gcd_algorithm(a, b):
    r_prev, r_curr = a, b
    s_prev, s_curr = 1, 0
    t_prev, t_curr = 0, 1
    while r_curr:
        q = r_prev // r_curr
        r_prev, r_curr = r_curr, r_prev - q * r_curr
        s_prev, s_curr = s_curr, s_prev - q * s_curr
        t_prev, t_curr = t_curr, t_prev - q * t_curr
    return r_prev, s_prev


def compute_binomial_coeffs(n, M):
    C = [0] * (n + 1)
    C[n] = 1
    for k in range(n - 1, -1, -1):
        C[k] = (C[k + 1] * (k + 1)) % M
        if not C[k]:
            break
    return C


