#include <bits/stdc++.h>
using namespace std;

pair<long long, long long> extended_gcd_algorithm(long long a, long long b) {
    long long r_prev = a, r_curr = b;
    long long s_prev = 1, s_curr = 0;
    long long t_prev = 0, t_curr = 1;
    while (r_curr != 0) {
        long long q = r_prev / r_curr;
        long long r_temp = r_prev - q * r_curr;
        r_prev = r_curr;
        r_curr = r_temp;

        long long s_temp = s_prev - q * s_curr;
        s_prev = s_curr;
        s_curr = s_temp;

        long long t_temp = t_prev - q * t_curr;
        t_prev = t_curr;
        t_curr = t_temp;
    }
    return {r_prev, s_prev};
}

vector<long long> compute_binomial_coeffs(int n, long long M) {
    vector<long long> C(n + 1, 0);
    C[n] = 1;
    for (int k = n - 1; k >= 0; --k) {
        C[k] = (C[k + 1] * (k + 1)) % M;
        if (C[k] == 0) {
            break;
        }
    }
    return C;
}

long long main_calculation(int n, long long M) {
    vector<vector<vector<long long>>> K;
    K.push_back({{1}});
    for (int i = 0; i < n - 1; ++i) {
        auto& prev_layer = K[i];
        int size_prev = (int)prev_layer.size();
        vector<vector<long long>> new_layer(size_prev + i + 1, vector<long long>(i + 2, 0));
        K.push_back(new_layer);
        for (int j = 0; j < size_prev; ++j) {
            for (int k = 0; k < (int)prev_layer[j].size(); ++k) {
                long long val = prev_layer[j][k];
                for (int h = 0; h <= i; ++h) {
                    K[i + 1][j + h][k] = (K[i + 1][j + h][k] + val) % M;
                }
                K[i + 1][j + i + 1][i + 1] = (K[i + 1][j + i + 1][i + 1] + val) % M;
            }
        }
    }
    vector<long long> C = compute_binomial_coeffs(n, M);
    long long total_sum = 0;
    for (int i = 1; i < n; ++i) {
        auto& layer = K[i];
        int ni = (int)layer.size();
        int mi = (int)layer[0].size();
        vector<vector<long long>> S(ni, vector<long long>(mi, 0));
        for (int j = 0; j < ni; ++j) {
            for (int k = 0; k < mi; ++k) {
                S[j][k] = layer[j][k];
            }
        }
        for (int j = 0; j < ni; ++j) {
            for (int k = mi - 2; k >= 0; --k) {
                S[j][k] = (S[j][k] + S[j][k + 1]) % M;
            }
        }
        for (int j = 1; j < ni; ++j) {
            for (int k = 0; k < mi; ++k) {
                S[j][k] = (S[j][k] + S[j - 1][k]) % M;
            }
        }
        long long sum_value = 0;
        for (int j = 1; j < ni; ++j) {
            for (int k = 0; k < mi - 1; ++k) {
                sum_value += (layer[j][k] * S[j - 1][k + 1]) % M;
                sum_value %= M;
            }
        }
        long long c = C[i + 1];
        sum_value = (sum_value * c) % M;
        total_sum = (total_sum + sum_value) % M;
    }
    return total_sum;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long m;
    cin >> n >> m;
    cout << main_calculation(n, m) << "\n";
    return 0;
}

